package io.github.some_example_name;
import io.github.some_example_name.database.*;import io.github.some_example_name.model.*;import java.util.*;
public final class DraftClass2004RegressionTest{public static void main(String[]a){require(DraftClassRepository.hasHistoricalClass(2004),"not registered");List<Player>ps=DraftClassRepository.getClassForYear(2004);require(ps.size()==60,"Expected 60");Set<String>old=new HashSet<>();for(int y=1970;y<=2003;y++)for(Player p:DraftClassRepository.getClassForYear(y))old.add(n(p.getName()));Map<String,Player>m=new HashMap<>();for(Player p:ps){require(p.getAge()==18,"age "+p.getName());require(!old.contains(n(p.getName())),"Repeated "+p.getName());require(m.put(p.getName(),p)==null,"Duplicate "+p.getName());}expect(m,"Manuel Neuer",Position.GK,13,49,82,91,21,98);expect(m,"Nani",Position.RW,69,70,34,90,86,91);expect(m,"Younès Kaboul",Position.CB,38,59,70,94,52,79);System.out.println("Draft class 2004: 60 unique prospects with pre-balanced potential OK.");}private static String n(String s){return s.toLowerCase(Locale.ROOT);}private static void expect(Map<String,Player>m,String n,Position q,int a,int p,int d,int f,int dr,int pot){Player x=m.get(n);require(x!=null&&x.getPrimaryPosition()==q&&x.getPotential()==pot&&x.getTechnicalAttributes().getAtaque()==a&&x.getTechnicalAttributes().getPasse()==p&&x.getTechnicalAttributes().getDefesa()==d&&x.getTechnicalAttributes().getFisico()==f&&x.getTechnicalAttributes().getDrible()==dr,"Bad "+n);}private static void require(boolean b,String s){if(!b)throw new AssertionError(s);}}
